    64	absl::AnyInvocable<void() noexcept> gpu_pipeline_executor::get_per_thread_init()
    65	{
    66	  int device_id          = _memory_space->get_device_id();
    67	  auto thread_id_counter = std::make_shared<std::atomic<uint32_t>>(0);
    68	
    69	  return [device_id,
    70	          telemetry_context = _telemetry_context,
    71	          thread_prefix     = _config.thread_name_prefix,
    72	          thread_id_counter]() mutable noexcept {
    73	    const int32_t thread_id = thread_id_counter->fetch_add(1, std::memory_order_relaxed);
    74	    telemetry::thread_local_executor_thread_telemtry_init(
    75	      *telemetry_context,
    76	      std::format("{}-gpu{}-exec-{}", thread_prefix, device_id, thread_id),
    77	      telemetry_context->executor_thread_group_id(device_id));
    78	
    79	    // Per-thread init runs on a worker thread just spawned by the
    80	    // bounded_pool. cudaSetDevice pins this thread to the executor's GPU
    81	    // context; silent failure would cause every downstream CUDA call on this
    82	    // thread to land on GPU 0 regardless of device_id. We cannot use
    83	    // CUCASCADE_CUDA_TRY here because the lambda is noexcept — inline the
    84	    // check instead.
    85	    cudaError_t err = cudaSetDevice(device_id);
    86	    if (err != cudaSuccess) {
    87	      SIRIUS_LOG_ERROR("gpu_pipeline_executor per-thread init: cudaSetDevice({}) failed: {}",
    88	                       device_id,
    89	                       cudaGetErrorString(err));
    90	    }
    91	    sirius::util::enable_log_on_default_stream();
    92	  };
    93	}
