    95	void gpu_pipeline_executor::manager_loop()
    96	{
    97	  telemetry::TaskManagerLoopThreadHandleWrapper manager_thread_telemetry{
    98	    *_telemetry_context,
    99	    std::format("gpu-{}-exec-manager", _memory_space->get_device_id()),
   100	    _telemetry_context->manager_thread_group_id(_memory_space->get_device_id())};
   101	
   102	  rmm::cuda_set_device_raii set_device_guard(rmm::cuda_device_id{_memory_space->get_device_id()});
   103	  sirius::util::enable_log_on_default_stream();
   104	  while (_running.load()) {
   105	    auto slot = _bounded_pool->reserve();  // block till a thread is available
   106	    if (!slot) {
   107	      SIRIUS_LOG_INFO("GPU Pipeline Executor: pool interrupted, stopping manager loop");
   108	      break;
   109	    }
   110	    // Pull-signal backpressure: now that we hold a reserved thread slot, tell the
   111	    // task_scheduler this device is ready for work. The scheduler will only move
   112	    // a task out of its downgrade-visible queue into our _task_queue when a
   113	    // ready signal has been received from us — preventing tasks from piling
   114	    // up here where the downgrade executor can't see them.
   115	    auto ready       = std::make_unique<task_request>();
   116	    ready->kind      = task_request_kind::device_ready;
   117	    ready->device_id = _memory_space->get_device_id();
   118	
   119	    std::unique_ptr<parallel::itask> pipeline_task = nullptr;
   120	    {
   121	      if (!_task_request_publisher.send(std::move(ready))) {
   122	        SIRIUS_LOG_INFO(
   123	          "GPU Pipeline Executor: task_request channel closed, stopping manager loop");
   124	        break;
   125	      }
   126	      pipeline_task = _task_queue.pop();  // block till a task is available
   127	    }
   128	    if (!pipeline_task) {
   129	      SIRIUS_LOG_INFO("GPU Pipeline Executor: task queue interrupted, stopping manager loop");
   130	      break;
   131	    }
   132	    auto* gpu_task = cast_to_gpu_pipeline_task(pipeline_task.get());
   133	    if (!gpu_task) {
   134	      SIRIUS_LOG_ERROR("GPU Pipeline Executor: Failed to cast pipeline task to gpu_pipeline_task");
   135	      if (_completion_handler) {
   136	        _completion_handler->report_error(
   137	          "GPU Pipeline Executor: Failed to cast pipeline task to gpu_pipeline_task");
   138	      }
   139	      break;
   140	    }
   141	    // Pass this executor's memory space so cross-space inputs (host/disk tiers and GPU data on
   142	    // another device, which prepare clones into this space) are counted in the reservation.
   143	    auto reservation_info = gpu_task->get_estimated_reservation_size_info(_memory_space);
   144	    auto bytes_needs      = reservation_info.reservation_size;
   145	    gpu_task->telemetry_handle().reserving({
   146	      .instance_name              = "",
   147	      .requested_bytes            = reservation_info.reservation_size,
   148	      .input_basis                = reservation_info.input_basis,
   149	      .peak_estimate              = reservation_info.peak_memory_estimate,
   150	      .bytes_to_materialize       = reservation_info.bytes_to_materialize_input,
   151	      .manager_thread_resource_id = manager_thread_telemetry.handle->uuid(),
   152	    });
   153	    // Clamp the reservation request to what this memory space can actually
   154	    // grant (its reservation limit). The history-based estimate can balloon far
   155	    // past capacity — a small input that once drove a near-cap peak yields a
   156	    // huge peak/estimate ratio that extrapolates to multi-GiB estimates on a
   157	    // GiB-budget GPU. make_reservation() then returns only a partial reservation
   158	    // and the downgrade predicate below (which must reserve the *full*
   159	    // bytes_needs) can never succeed, so the task livelocks through the
   160	    // OOM-reschedule loop until the retry cap trips and the query fails. Capping
   161	    // at get_max_memory() keeps both the reservation and the downgrade target
   162	    // achievable; any per-batch overflow during execution is still handled by
   163	    // the OOM-reschedule + tiering path. (Telemetry above intentionally reports
   164	    // the pre-clamp estimate so the estimator can still be analyzed.)
   165	    if (auto const space_max = _memory_space->get_max_memory();
   166	        space_max > 0 && bytes_needs > space_max) {
   167	      SIRIUS_LOG_DEBUG(
   168	        "GPU Pipeline Executor: clamping reservation request {} -> {} bytes (space max) for "
   169	        "pipeline {} task {}",
   170	        bytes_needs,
   171	        space_max,
   172	        gpu_task->get_pipeline_id(),
   173	        gpu_task->get_task_id());
   174	      bytes_needs = space_max;
   175	    }
   176	    SIRIUS_LOG_TRACE(
   177	      "[GPU:{}] GPU Pipeline Executor: Acquiring memory reservation for pipeline {} of {} bytes "
   178	      "for task {}. Memory available: {}, total reserved: {}, max: {}",
   179	      _memory_space->get_device_id(),
   180	      gpu_task->get_pipeline_id(),
   181	      bytes_needs,
   182	      gpu_task->get_task_id(),
   183	      _memory_space->get_available_memory(),
   184	      _memory_space->get_total_reserved_memory(),
   185	      _memory_space->get_max_memory());
   186	    auto reservation = _memory_space->make_reservation(bytes_needs);
   187	    if (!reservation) {
   188	      SIRIUS_LOG_ERROR("GPU Pipeline Executor: Failed to acquire memory reservation for task {}",
   189	                       gpu_task->get_task_id());
   190	      if (_completion_handler) {
   191	        _completion_handler->report_error(
   192	          "GPU Pipeline Executor: Failed to acquire memory reservation for task " +
   193	          std::to_string(gpu_task->get_task_id()));
   194	      }
   195	      break;
   196	    } else if (reservation->size() < bytes_needs && _downgrade_executor) {
   197	      size_t shortfall    = bytes_needs - reservation->size();
   198	      size_t partial_size = reservation->size();
   199	
   200	      gpu_task->telemetry_handle().downgrading({
   201	        .instance_name              = "",
   202	        .shortfall_bytes            = shortfall,
   203	        .partial_bytes              = partial_size,
   204	        .manager_thread_resource_id = manager_thread_telemetry.handle->uuid(),
   205	      });
   206	
   207	      SIRIUS_LOG_DEBUG(
   208	        "GPU Pipeline Executor: requested reservation size {} but only got {} bytes, reservation "
   209	        "shortfall {} bytes for pipeline {} "
   210	        "task {}, requesting predicate-based downgrade",
   211	        bytes_needs,
   212	        partial_size,
   213	        shortfall,
   214	        gpu_task->get_pipeline_id(),
   215	        gpu_task->get_task_id());
   216	
   217	      reservation.reset();  // release partial reservation before downgrade
   218	
   219	      std::unique_ptr<cucascade::memory::reservation> new_reservation;
   220	      auto* mem_space = _memory_space;
   221	      size_t freed    = 0;
   222	      std::mutex reservation_mutex;
   223	      try {
   224	        freed =
   225	          _downgrade_executor
   226	            ->request_downgrade([mem_space, bytes_needs, &new_reservation, &reservation_mutex]() {
   227	              std::lock_guard<std::mutex> lock(reservation_mutex);
   228	              if (new_reservation) { return true; }
   229	              auto res = mem_space->make_reservation_or_null(bytes_needs);
   230	              if (res && res->size() >= bytes_needs) { new_reservation = std::move(res); }
   231	              return new_reservation != nullptr;
   232	            })
   233	            .get();
   234	      } catch (const std::exception& e) {
   235	        SIRIUS_LOG_INFO("GPU Pipeline Executor: downgrade request cancelled for task {}: {}",
   236	                        gpu_task->get_task_id(),
   237	                        e.what());
   238	        break;
   239	      }
   240	
   241	      if (new_reservation) {
   242	        reservation = std::move(new_reservation);
   243	      } else {
   244	        // Predicate never succeeded — try one final reservation attempt
   245	        reservation = _memory_space->make_reservation(bytes_needs);
   246	      }
   247	
   248	      if (!reservation) {
   249	        SIRIUS_LOG_ERROR(
   250	          "GPU Pipeline Executor: Failed to acquire memory reservation after "
   251	          "downgrade for task {} (freed {} bytes)",
   252	          gpu_task->get_task_id(),
   253	          freed);
   254	        if (_completion_handler) {
   255	          _completion_handler->report_error(
   256	            "GPU Pipeline Executor: Failed to acquire memory reservation "
   257	            "after downgrade for task " +
   258	            std::to_string(gpu_task->get_task_id()));
   259	        }
   260	        break;
   261	      }
   262	      if (reservation->size() < bytes_needs) {
   263	        SIRIUS_LOG_WARN(
   264	          "GPU Pipeline Executor: after downgrade ({} bytes freed), reservation "
   265	          "still partial ({}/{} bytes) for pipeline {} task {} -- proceeding "
   266	          "with partial reservation",
   267	          freed,
   268	          reservation->size(),
   269	          bytes_needs,
   270	          gpu_task->get_pipeline_id(),
   271	          gpu_task->get_task_id());
   272	      }
   273	    } else if (reservation->size() < bytes_needs) {
   274	      // No downgrade executor available -- warn and proceed (this should never happen)
   275	      SIRIUS_LOG_WARN(
   276	        "GPU Pipeline Executor: Acquired memory reservation does not match "
   277	        "requested size for pipeline {} of {} bytes needed for task "
   278	        "{}. Reservation size: {}. WARNING: Downgrade executor is not available",
   279	        gpu_task->get_pipeline_id(),
   280	        bytes_needs,
   281	        gpu_task->get_task_id(),
   282	        reservation->size());
   283	    }
   284	    if (auto* local_state = dynamic_cast<sirius::pipeline::sirius_pipeline_task_local_state*>(
   285	          gpu_task->local_state())) {
   286	      local_state->set_reservation(std::move(reservation), reservation_info);
   287	    } else {
   288	      SIRIUS_LOG_ERROR("GPU Pipeline Executor: Failed to cast local state for task {}",
   289	                       gpu_task->get_task_id());
   290	      if (_completion_handler) {
   291	        _completion_handler->report_error(
   292	          "GPU Pipeline Executor: Failed to cast local state for task " +
   293	          std::to_string(gpu_task->get_task_id()));
   294	      }
   295	      break;
   296	    }
   297	    auto output_consumers = gpu_task->get_output_consumers();
   298	    auto* pipeline        = gpu_task->get_pipeline();
   299	    auto exc_stream       = _stream_pool.acquire_stream(
   300	      cucascade::memory::exclusive_stream_pool::stream_acquire_policy::GROW);
   301	    _bounded_pool->dispatch(
   302	      std::move(slot),
   303	      [this,
   304	       task       = std::move(pipeline_task),
   305	       exc_stream = std::move(exc_stream),
   306	       consumers  = std::move(output_consumers),
   307	       pipeline]() mutable {
   308	        try {
   309	          task->execute(exc_stream);
   310	          _tasks_executed.fetch_add(1, std::memory_order_relaxed);
   311	        } catch (task_reschedule_exception& ex) {
   312	          if (_completion_handler && _completion_handler->has_error()) {
   313	            // If the completion handler is already in an error state, then we can just return and
   314	            // not try to reschedule
   315	            return;
   316	          }
   317	          auto* gpu_task = cast_to_gpu_pipeline_task(task.get());
   318	          if (!gpu_task) {
   319	            SIRIUS_LOG_ERROR("GPU Pipeline Executor: Failed to cast task for reschedule");
   320	            if (_completion_handler) {
   321	              _completion_handler->report_error(
   322	                "GPU Pipeline Executor: Failed to cast task for reschedule");
   323	            }
   324	            return;
   325	          }
   326	
   327	          // Sync the stream to ensure all memory is released before the reschedule.
   328	          exc_stream->synchronize();
   329	
   330	          // Determine retry count and original task ID for this rescheduled attempt.
   331	          auto* cur_local = dynamic_cast<gpu_pipeline_task_local_state*>(gpu_task->local_state());
   332	          uint32_t next_retry_count = 1;
   333	          uint64_t orig_task_id     = gpu_task->get_task_id();
   334	          if (cur_local && cur_local->original_task_id.has_value()) {
   335	            next_retry_count = cur_local->retry_count + 1;
   336	            orig_task_id     = cur_local->original_task_id.value();
   337	          }
   338	
   339	          // Bumped from 10 to 100 as part of follow-up #17. SF100 Q11 with
   340	          // cache=table_gpu + num_gpus=2 exhausted the old 10-retry budget
   341	          // against cross-GPU BUILD_PROBE batch-lock contention: the batch
   342	          // was held in `processing` on one GPU while the probe task on the
   343	          // other GPU needed it. Each convert-release cycle is O(100ms) at
   344	          // SF100 scale, so 10 retries × 5ms backoff (50 ms total) was far
   345	          // too short. With 100 retries × 50 ms backoff (~5 s) the probe
   346	          // tasks get enough patience to clear the contention window while
   347	          // still bailing out on truly wedged queries.
   348	          static constexpr uint32_t MAX_RETRIES = 100;
   349	          if (next_retry_count > MAX_RETRIES) {
   350	            SIRIUS_LOG_ERROR(
   351	              "GPU Pipeline Executor: task {} (original task {}) exceeded {} retries at "
   352	              "operator index {} — terminating query: {}",
   353	              gpu_task->get_task_id(),
   354	              orig_task_id,
   355	              MAX_RETRIES,
   356	              ex.get_resume_operator_index(),
   357	              ex.what());
   358	            if (_completion_handler) {
   359	              _completion_handler->report_error(std::make_exception_ptr(std::runtime_error(
   360	                "GPU pipeline task exceeded maximum retry limit (" + std::to_string(MAX_RETRIES) +
   361	                ") for original task " + std::to_string(orig_task_id) + ": " + ex.what())));
   362	            }
   363	            return;
   364	          }
   365	
   366	          SIRIUS_LOG_WARN(
   367	            "GPU Pipeline Executor: reschedule (retry {}/{}) for task {} (original task {}), "
   368	            "resuming from operator index {}: {}",
   369	            next_retry_count,
   370	            MAX_RETRIES,
   371	            gpu_task->get_task_id(),
   372	            orig_task_id,
   373	            ex.get_resume_operator_index(),
   374	            ex.what());
   375	
   376	          auto intermediate_data = ex.release_intermediate_data();
   377	          if (auto pipelineable_data =
   378	                dynamic_cast<op::pipelineable_operator_data*>(intermediate_data.get())) {
   379	            // We want to release the read-only lock on the data so that when its added back to the
   380	            // task queue it could be downgraded if needed.
   381	            pipelineable_data->remove_read_only_lock();
   382	          }
   383	
   384	          // Build the rescheduled task via virtual factory (preserves derived type).
   385	          auto new_local_state = std::make_unique<gpu_pipeline_task_local_state>(
   386	            std::move(intermediate_data), ex.get_resume_operator_index());
   387	          new_local_state->retry_count      = next_retry_count;
   388	          new_local_state->original_task_id = orig_task_id;
   389	          if (cur_local) { new_local_state->inherit_retry_reservation_floor(*cur_local); }
   390	
   391	          // Preserve the per-task device pin across reschedule. Dropping it lets
   392	          // an OOM'd partition task scatter to the wrong GPU and touch a cuco
   393	          // table built on another device (cudaErrorInvalidValue). Only the
   394	          // local_state pin needs copying; a global-state pin already survives.
   395	          if (cur_local && cur_local->get_preferred_device_id().has_value()) {
   396	            new_local_state->set_preferred_device_id(cur_local->get_preferred_device_id().value());
   397	          }
   398	
   399	          auto new_task_id =
   400	            _task_creator ? _task_creator->get_next_task_id() : gpu_task->get_task_id();
   401	          auto new_task =
   402	            gpu_task->create_rescheduled_task(new_task_id, std::move(new_local_state));
   403	
   404	          // Backoff before rescheduling to allow other tasks to complete and
   405	          // free memory (true OOM case) or release a contended batch
   406	          // (cross-GPU processing contention, follow-up #17). 50 ms gives
   407	          // typical SF100 probe tasks time to finish their current work
   408	          // without putting the rescheduled task into a tight busy-spin.
   409	          std::this_thread::sleep_for(std::chrono::milliseconds(50));
   410	
   411	          // Schedule the rescheduled task. It goes back through manager_loop()
   412	          // to acquire a fresh reservation before execution.
   413	          if (auto* pipeline_task = dynamic_cast<sirius_pipeline_itask*>(task.get())) {
   414	            pipeline_task->telemetry_handle().finalizing({
   415	              .instance_name = "",
   416	              .success       = false,
   417	            });
   418	            pipeline_task->telemetry_handle().exit();
   419	            pipeline_task->set_telemetry_finalized();
   420	          }
   421	          this->schedule(std::move(new_task));
   422	          return;
   423	        } catch (const std::exception& e) {
   424	          SIRIUS_LOG_ERROR("GPU Pipeline Executor: Exception during task execution: {}", e.what());
   425	          if (_task_creator) { _task_creator->stop(); }
   426	          if (_completion_handler) { _completion_handler->report_error(std::current_exception()); }
   427	          return;
   428	        } catch (...) {
   429	          SIRIUS_LOG_ERROR("GPU Pipeline Executor: unknown error during task execution");
   430	          if (_task_creator) { _task_creator->stop(); }
   431	          if (_completion_handler) { _completion_handler->report_error(std::current_exception()); }
   432	          return;
   433	        }
   434	        if (auto* pipeline_task = dynamic_cast<sirius_pipeline_itask*>(task.get())) {
   435	          pipeline_task->telemetry_handle().finalizing({
   436	            .instance_name = "",
   437	            .success       = true,
   438	          });
   439	          pipeline_task->telemetry_handle().exit();
   440	          pipeline_task->set_telemetry_finalized();
   441	        }
   442	        task.reset();
   443	
   444	        // Check if query is complete BEFORE scheduling downstream tasks.
   445	        // mark_completed() signals the future that engine.execute() is waiting on,
   446	        // which may destroy the engine and its operators. We must not schedule
   447	        // tasks that reference those operators after signaling completion.
   448	        bool query_complete = false;
   449	        if (_completion_handler && pipeline && pipeline->is_query_terminal()) {
   450	          query_complete = pipeline->is_pipeline_finished();
   451	        }
   452	
   453	        if (!query_complete && _task_creator) {
   454	          // Schedule consumers explicitly here to drive the scheduler's
   455	          // round-robin rotation per-batch. notify_downstream_pipelines() in
   456	          // the task destructor only fires once the pipeline drains —
   457	          // mid-pipeline batches need to start rotating before that point so
   458	          // they reach all GPUs.
   459	          for (auto* consumer : consumers) {
   460	            if (consumer) { _task_creator->schedule(consumer); }
   461	          }
   462	        }
   463	
   464	        if (query_complete && _completion_handler) {
   465	          _task_creator->drain_pending_tasks();
   466	          _completion_handler->mark_completed();
   467	        }
   468	      });
   469	  }
   470	}
