   472	gpu_pipeline_task* gpu_pipeline_executor::cast_to_gpu_pipeline_task(sirius::parallel::itask* task)
   473	{
   474	  // Safely cast to gpu_pipeline_task
   475	  return dynamic_cast<gpu_pipeline_task*>(task);
