127	class oom_test_task_base : public sirius::pipeline::gpu_pipeline_task {
128	 public:
129	  oom_test_task_base(uint64_t task_id,
130	                     std::unique_ptr<sirius::pipeline::gpu_pipeline_task_local_state> local_state,
131	                     std::shared_ptr<oom_test_global_state> global_state)
132	    : gpu_pipeline_task(task_id,
133	                        std::vector<cucascade::shared_data_repository*>{},
134	                        std::move(local_state),
135	                        std::move(global_state))
136	  {
137	  }
138	
139	  std::unique_ptr<sirius::op::operator_data> compute_task(rmm::cuda_stream_view) override
140	  {
141	    return nullptr;
142	  }
143	
144	  void publish_output(sirius::op::operator_data&, rmm::cuda_stream_view) override {}
145	
146	  sirius::pipeline::reservation_size_info get_estimated_reservation_size_info(
147	    const cucascade::memory::memory_space* /*target_space*/) const override
148	  {
149	    sirius::pipeline::reservation_size_info info;
150	    info.reservation_size = kReservationSize;
151	    return info;
152	  }
153	
154	  std::vector<sirius::op::sirius_physical_operator*> get_output_consumers() override { return {}; }
155	
156	 protected:
157	  // RAII guard that resets the stream reservation on destruction.
158	  struct allocator_guard {
159	    cucascade::memory::reservation_aware_resource_adaptor* allocator;
160	    rmm::cuda_stream_view stream;
161	
162	    allocator_guard(cucascade::memory::reservation_aware_resource_adaptor* a,
163	                    rmm::cuda_stream_view s)
164	      : allocator(a), stream(s)
165	    {
166	    }
167	    ~allocator_guard() { allocator->reset_stream_reservation(stream); }
168	
169	    allocator_guard(const allocator_guard&)            = delete;
170	    allocator_guard& operator=(const allocator_guard&) = delete;
171	    allocator_guard(allocator_guard&&)                 = delete;
172	    allocator_guard& operator=(allocator_guard&&)      = delete;
173	  };
174	
175	  // Performs the common reservation → allocator → attach → cleanup setup.
176	  // Returns the allocator guard on success, or nullptr on failure (after
177	  // recording an error on global_state).
178	  std::unique_ptr<allocator_guard> setup_allocator(rmm::cuda_stream_view stream,
179	                                                   const std::string& task_label)
180	  {
181	    auto& global = _global_state->cast<oom_test_global_state>();
182	    auto& local  = _local_state->cast<sirius::pipeline::gpu_pipeline_task_local_state>();
183	
184	    auto reservation = local.release_reservation();
185	    if (!reservation) {
186	      global.add_error("Missing GPU memory reservation for " + task_label + ".");
187	      return nullptr;
188	    }
189	
190	    auto* allocator =
191	      reservation->get_memory_resource_as<cucascade::memory::reservation_aware_resource_adaptor>();
192	    if (!allocator) {
193	      global.add_error("Missing reservation-aware allocator for " + task_label + ".");
194	      return nullptr;
195	    }
196	
197	    if (!allocator->attach_reservation_to_tracker(
198	          stream,
199	          std::move(reservation),
200	          std::make_unique<cucascade::memory::ignore_reservation_limit_policy>(),
201	          nullptr)) {
202	      global.add_error("Failed to attach reservation to stream tracker for " + task_label + ".");
203	      return nullptr;
204	    }
205	
206	    return std::make_unique<allocator_guard>(allocator, stream);
207	  }
208	};
