343	// ---------------------------------------------------------------------------
344	// Memory layout for the reschedule test:
345	//   Allocation    = 400 MB per task (much larger than the 50 MB reservation)
346	//
347	// With 3 threads, all 3 tasks start concurrently.
348	// Accounting after 3 reservations: 150 MB
349	// First  allocation (+350 MB overflow): total =  500 MB ≤ 1100 → OK
350	// Second allocation (+350 MB overflow): total =  850 MB ≤ 1100 → OK
351	// Third  allocation (+350 MB overflow): total = 1200 MB > 1100 → OOM!
352	//
353	// The OOM'd task gets rescheduled. After the first two complete, enough
354	// accounting headroom is freed for the rescheduled task to succeed.
355	// (Note: cucascade's cross-boundary deallocation accounting leaves some
356	//  residual in _total_allocated_bytes, hence the extra capacity margin.)
357	// ---------------------------------------------------------------------------
358	TEST_CASE("GPU pipeline executor reschedules tasks on OOM", "[gpu_pipeline_executor][oom]")
359	{
360	  oom_test_fixture f;
361	  if (!f.setup(3, "oom-test")) {
362	    WARN("Skipping OOM reschedule test — no GPU available.");
363	    return;
364	  }
365	
366	  auto global_state = std::make_shared<oom_test_global_state>();
367	
368	  const int num_tasks = 3;
369	  std::atomic<int> dispatched{0};
370	
371	  f.executor->start();
372	
373	  // Post-v1.0 push-model (commit 90dc104): gpu_pipeline_executor no longer publishes
374	  // task_requests. Schedule tasks directly onto the executor instead of waiting on
375	  // f.request_channel.get(). The request_channel is kept wired to preserve the
376	  // fixture API but is not used at runtime.
377	  std::thread request_handler([&]() {
378	    while (dispatched.load(std::memory_order_relaxed) < num_tasks) {
379	      auto local_state = std::make_unique<sirius::pipeline::gpu_pipeline_task_local_state>(
380	        std::make_unique<sirius::op::pipelineable_operator_data>(
381	          std::vector<std::shared_ptr<cucascade::data_batch>>{}));
382	      auto task = std::make_unique<oom_test_task>(
383	        static_cast<uint64_t>(dispatched.load(std::memory_order_relaxed)),
384	        std::move(local_state),
385	        global_state);
386	      f.executor->schedule(std::move(task));
387	      dispatched.fetch_add(1, std::memory_order_relaxed);
388	    }
389	  });
390	
391	  //--------------------------------------------------------------------------
392	  // Wait for all tasks to complete (including rescheduled ones)
393	  //--------------------------------------------------------------------------
394	  auto start_time = std::chrono::steady_clock::now();
395	  auto timeout    = std::chrono::seconds(30);
396	  while (global_state->completed_count.load(std::memory_order_relaxed) < num_tasks) {
397	    std::this_thread::sleep_for(std::chrono::milliseconds(50));
398	    if (std::chrono::steady_clock::now() - start_time > timeout) {
399	      f.executor->stop();
400	      f.request_channel.close();
401	      request_handler.join();
402	      FAIL("Timed out waiting for OOM rescheduled tasks to complete. "
403	           << "Completed: " << global_state->completed_count.load()
404	           << ", OOM count: " << global_state->oom_count.load());
405	    }
406	  }
407	
408	  f.executor->stop();
409	  f.request_channel.close();
410	  request_handler.join();
411	
412	  //--------------------------------------------------------------------------
413	  // Validate results
414	  //--------------------------------------------------------------------------
415	  if (global_state->error_count.load(std::memory_order_relaxed) > 0) {
416	    std::lock_guard<std::mutex> lock(global_state->error_mutex);
417	    for (const auto& error : global_state->errors) {
418	      INFO(error);
419	    }
420	  }
421	
422	  REQUIRE(global_state->error_count.load(std::memory_order_relaxed) == 0);
423	  REQUIRE(global_state->completed_count.load(std::memory_order_relaxed) == num_tasks);
424	  // At least one task should have OOM'd and been rescheduled
425	  REQUIRE(global_state->oom_count.load(std::memory_order_relaxed) >= 1);
426	
427	  INFO("OOM reschedule test passed: " << global_state->oom_count.load() << " task(s) rescheduled, "
428	                                      << num_tasks << " completed successfully");
429	}
430	
431	// ---------------------------------------------------------------------------
432	// Test: tasks that can never succeed exhaust their retry budget (MAX_OOM_RETRIES=10)
433	// and cause the query to fail, while small tasks that fit in memory still complete.
434	//
435	// Memory layout:
436	//   GPU capacity  = 1100 MB
437	//   small_task    =    1 MB allocation  → always succeeds
438	//   xl_task       = 2048 MB allocation  → always OOMs (exceeds capacity)
439	//
440	// We dispatch 5 small tasks + 3 XL tasks = 8 total.
441	// The XL tasks will be rescheduled up to 10 times each before the executor
442	// reports a max-retry error on the completion handler.
443	// The 5 small tasks should all complete regardless.
444	// After the error, drain_and_wait() should empty the task queue.
445	// ---------------------------------------------------------------------------
446	TEST_CASE("GPU pipeline executor fails after max OOM retries",
447	          "[gpu_pipeline_executor][oom][max_retries]")
448	{
449	  oom_test_fixture f;
450	  if (!f.setup(3, "oom-retry")) {
451	    WARN("Skipping max-retry OOM test — no GPU available.");
452	    return;
453	  }
454	
455	  auto global_state = std::make_shared<oom_test_global_state>();
456	
457	  const int num_small = 5;
458	  const int num_xl    = 3;
459	  const int num_tasks = num_small + num_xl;
460	  std::atomic<int> dispatched{0};
461	
462	  f.executor->start();
463	
464	  // Post-v1.0 push-model (commit 90dc104): schedule tasks directly instead of
465	  // waiting on request_channel.get(). First num_small tasks become small_tasks,
466	  // the rest xl_tasks.
467	  std::thread request_handler([&]() {
468	    while (dispatched.load(std::memory_order_relaxed) < num_tasks) {
469	      auto id          = static_cast<uint64_t>(dispatched.load(std::memory_order_relaxed));
470	      auto local_state = std::make_unique<sirius::pipeline::gpu_pipeline_task_local_state>(
471	        std::make_unique<sirius::op::pipelineable_operator_data>(
472	          std::vector<std::shared_ptr<cucascade::data_batch>>{}));
473	
474	      std::unique_ptr<sirius::parallel::itask> task;
475	      if (id < static_cast<uint64_t>(num_small)) {
476	        task = std::make_unique<small_task>(id, std::move(local_state), global_state);
477	      } else {
478	        task = std::make_unique<xl_task>(id, std::move(local_state), global_state);
479	      }
480	      f.executor->schedule(std::move(task));
481	      dispatched.fetch_add(1, std::memory_order_relaxed);
482	    }
483	  });
484	
485	  //--------------------------------------------------------------------------
486	  // Wait for the completion handler to report an error (max retries exceeded)
487	  //--------------------------------------------------------------------------
488	  auto start_time = std::chrono::steady_clock::now();
489	  auto timeout    = std::chrono::seconds(60);
490	  while (!f.completion.has_error()) {
491	    std::this_thread::sleep_for(std::chrono::milliseconds(50));
492	    if (std::chrono::steady_clock::now() - start_time > timeout) {
493	      f.executor->stop();
494	      f.request_channel.close();
495	      request_handler.join();
496	      FAIL("Timed out waiting for max-retry OOM error. "
497	           << "Completed: " << global_state->completed_count.load()
498	           << ", OOM count: " << global_state->oom_count.load());
499	    }
500	  }
501	
502	  //--------------------------------------------------------------------------
503	  // Drain remaining tasks and shut down
504	  //--------------------------------------------------------------------------
505	  f.executor->drain_and_wait();
506	  f.request_channel.close();
507	  request_handler.join();
508	  f.executor->stop();
509	
510	  //--------------------------------------------------------------------------
511	  // Validate results
512	  //--------------------------------------------------------------------------
513	  if (global_state->error_count.load(std::memory_order_relaxed) > 0) {
514	    std::lock_guard<std::mutex> lock(global_state->error_mutex);
515	    for (const auto& error : global_state->errors) {
516	      INFO(error);
517	    }
518	  }
519	
520	  // All small tasks should have completed successfully.
521	  REQUIRE(global_state->error_count.load(std::memory_order_relaxed) == 0);
522	  REQUIRE(global_state->completed_count.load(std::memory_order_relaxed) == num_small);
523	
524	  // The completion handler should be in an error state from exceeding max retries.
