140	    }
141	    // Pass this executor's memory space so cross-space inputs (host/disk tiers and GPU data on
142	    // another device, which prepare clones into this space) are counted in the reservation.
143	    auto reservation_info = gpu_task->get_estimated_reservation_size_info(_memory_space);
144	    auto bytes_needs      = reservation_info.reservation_size;
145	    gpu_task->telemetry_handle().reserving({
146	      .instance_name              = "",
147	      .requested_bytes            = reservation_info.reservation_size,
148	      .input_basis                = reservation_info.input_basis,
149	      .peak_estimate              = reservation_info.peak_memory_estimate,
150	      .bytes_to_materialize       = reservation_info.bytes_to_materialize_input,
151	      .manager_thread_resource_id = manager_thread_telemetry.handle->uuid(),
152	    });
