245	        reservation = _memory_space->make_reservation(bytes_needs);
246	      }
247	
248	      if (!reservation) {
249	        SIRIUS_LOG_ERROR(
250	          "GPU Pipeline Executor: Failed to acquire memory reservation after "
251	          "downgrade for task {} (freed {} bytes)",
252	          gpu_task->get_task_id(),
253	          freed);
254	        if (_completion_handler) {
255	          _completion_handler->report_error(
256	            "GPU Pipeline Executor: Failed to acquire memory reservation "
257	            "after downgrade for task " +
258	            std::to_string(gpu_task->get_task_id()));
259	        }
260	        break;
261	      }
262	      if (reservation->size() < bytes_needs) {
263	        SIRIUS_LOG_WARN(
264	          "GPU Pipeline Executor: after downgrade ({} bytes freed), reservation "
265	          "still partial ({}/{} bytes) for pipeline {} task {} -- proceeding "
266	          "with partial reservation",
267	          freed,
268	          reservation->size(),
269	          bytes_needs,
270	          gpu_task->get_pipeline_id(),
271	          gpu_task->get_task_id());
272	      }
273	    } else if (reservation->size() < bytes_needs) {
274	      // No downgrade executor available -- warn and proceed (this should never happen)
275	      SIRIUS_LOG_WARN(
276	        "GPU Pipeline Executor: Acquired memory reservation does not match "
277	        "requested size for pipeline {} of {} bytes needed for task "
278	        "{}. Reservation size: {}. WARNING: Downgrade executor is not available",
279	        gpu_task->get_pipeline_id(),
280	        bytes_needs,
281	        gpu_task->get_task_id(),
282	        reservation->size());
283	    }
284	    if (auto* local_state = dynamic_cast<sirius::pipeline::sirius_pipeline_task_local_state*>(
